function renderVisual(v,stage=0,q=null){if(!v)return '';let html=pr2AdvancedVisual(v,stage,q);if(html===null)html=pr1Visual(v,stage,q);if(html===null){html=renderVisualBase(v);let support=stageSupportSVG(v,stage,q);if(support)html=html.replace('</svg>',`${support}</svg>`)}if(q){let description=`${q.title[state.lang]}. ${t('visualLabel')}`;html=html.replace(/aria-label="[^"]*"/,`aria-label="${escapeHTML(description)}"`)}return html+(q?visualHintCopy(q,ensureEvidence(q.id)):'')}

function coachCopy(q,e){let en=state.lang==='en';if(e.status==='independent')return [en?'Independent success':'Berhasil mandiri',t('correctIndependent'),'celebrate'];if(e.status==='recovered')return [en?'Useful recovery':'Perbaikan yang bermakna',t('correctRecovered'),'encourage'];if(e.status==='rescued')return [en?'Rebuild this structure once more':'Bangun ulang struktur ini sekali lagi',t('rescuedMsg'),'hint'];if(e.status==='supported')return [en?'Support helped unlock the method':'Bantuan membantu membuka metode',t('correctSupported'),'encourage'];if(e.attempts>=2)return [en?'Keep the geometry, narrow the check':'Pertahankan geometrinya, persempit pengecekan',wrongFeedback(q,e),'alert'];if(e.hints)return [en?'Use the hint to notice structure':'Gunakan petunjuk untuk melihat struktur',stuckSupport(q,0),'hint'];return [en?'Read the geometry first':'Baca geometrinya dulu',en?'Identify the target triangle, then classify what is known before choosing a trigonometric rule.':'Tentukan segitiga target, lalu kelompokkan informasi yang diketahui sebelum memilih aturan trigonometri.','thinking']}
function statusLabel(e){if(!e)return t('notAttempted');if(e.status==='independent')return t('independent');if(e.status==='supported')return t('supported');if(e.status==='recovered')return t('recovered');if(e.status==='rescued')return t('rescued');if(e.skipped)return t('skipped');return t('unresolved')}

function renderPractice(){let q=cur(),e=ensureEvidence(q.id),pct=Math.round((state.idx/state.take.length)*100);let draft=questionDraft(q.id);let fields=q.check.mode==='auto'?`<div class="answer-grid">${q.check.fields.map((f,i)=>{let ok=e.fieldValidity?.[i]===true,bad=e.fieldValidity?.[i]===false,disabled=(e.status&&e.status!=='needs-review')||ok;return `<div class="field"><label for="answer-${q.id}-${i}">${f.label[state.lang]}</label><input id="answer-${q.id}-${i}" data-answer-field="${i}" class="${ok?'field-ok':bad?'field-bad':''}" aria-invalid="${bad?'true':'false'}" value="${escapeHTML(draft.answers[i]||'')}" placeholder="${escapeHTML(f.placeholder||'')}" ${disabled?'disabled':''}/>${ok?`<span class="field-state field-state-ok">${state.lang==='en'?'Correct · kept':'Benar · disimpan'}</span>`:bad?`<span class="field-state field-state-bad">${state.lang==='en'?'Review this field':'Periksa bagian ini'}</span>`:''}</div>`}).join('')}</div>`:`<div class="feedback warn">${t('selfIntro')}</div>`;let hintText=e.hints?`<div class="hint-box"><strong>${t('hint')} ${e.hints}</strong><div>${q.hints[state.lang][Math.min(e.hints-1,q.hints[state.lang].length-1)]}</div></div>`:'';let rescueButton=e.rescueAvailable&&!e.rescueUsed?`<button class="rescue-btn" onclick="useRescue()">${t('rescue')}</button>`:'';let guide=state.teacherReveal?`<div class="solution"><strong>${t('compare')}</strong><div>${q.solution[state.lang]}</div>${q.check.mode==='self'&&!e.rescueUsed&&!isResolvedEvidence(e)&&state.teacherRevealSource!=='teacher'?`<div class="self-check-row"><button class="secondary" onclick="selfAssess(true)">${t('matches')}</button><button class="secondary" onclick="selfAssess(false)">${t('again')}</button></div>`:''}${e.rescueUsed&&(!e.status||e.status==='needs-review')?`<div class="self-check-row"><button class="primary" onclick="markRescued()">${t('rescueDone')}</button></div>`:''}</div>`:'';let stuck=state.stuckOpen?`<div class="hint-box"><strong>${t('stuckTitle')}</strong><div class="tool-list" style="margin-top:9px">${[t('stuckStart'),t('stuckMethod'),t('stuckCalc'),t('stuckAsk')].map((x,i)=>`<button class="secondary" onclick="chooseStuck(${i})">${x}</button>`).join('')}</div></div>`:'';let [coachTitle,coachText,coachMascot]=coachCopy(q,e);return `<div class="shell">${topbar()}<main class="practice-shell"><div class="practice-head"><div><span class="pill">${levelName(q.level)}</span> <span class="pill">${q.id}</span></div><div class="center tiny">${state.teacherSession?(state.lang==='en'?'Teacher preview':'Pratinjau Guru'):`${t('take')} · ${t(state.mode)}`}</div><div class="right"><span class="timer" id="timer">0:00</span></div></div><div class="progress"><div style="width:${pct}%"></div></div><div class="question-layout"><section class="panel question-card"><div class="q-meta"><span class="q-id">${t('question')} ${state.idx+1} ${t('of')} ${state.take.length}</span><span class="family">· ${familyName(q.family)}</span></div><h2>${q.title[state.lang]}</h2><div class="prompt">${q.prompt[state.lang]}</div><div id="question-visual">${renderVisual(q.visual,Math.min(e.hints,3),q)}</div><div class="answer-area">${fields}<div class="scratch"><label class="tiny"><strong>${t('scratch')}</strong></label><textarea aria-label="${t('scratch')}" placeholder="${t('scratchPh')}">${escapeHTML(draft.work)}</textarea></div><div class="action-row"><button class="primary" onclick="checkAnswer()">${q.check.mode==='auto'?t('check'):t('showGuide')}</button><button class="secondary" onclick="showHint()">${t('hint')}</button><button class="secondary" onclick="openStuck()">${t('stuck')}</button>${rescueButton}</div><div id="message-copy">${state.message?`<div class="feedback ${state.message.type}">${state.message.text}</div>`:''}</div><div id="hint-copy">${hintText}</div>${stuck}${guide}</div></section><aside class="side-stack"><section class="panel coach"><img src="${mascot(coachMascot)}" alt=""/><div><strong>${coachTitle}</strong><p>${coachText}</p></div></section><section class="panel tools"><h3>${state.lang==='en'?'Practice controls':'Kontrol latihan'}</h3><div class="tool-list"><button class="secondary" onclick="skipQuestion()" ${isResolvedEvidence(e)?'disabled':''}>${t('skip')}</button><button class="secondary" onclick="changeProblem()" ${isResolvedEvidence(e)?'disabled':''}>${t('change')}</button>${(state.history.length||state.idx>0)?`<button class="secondary" onclick="previousQuestion()">${t('previous')}</button>`:''}${e.status&&e.status!=='needs-review'?(state.idx<state.take.length-1?`<button class="primary" onclick="nextQuestion()">${t('next')}</button>`:`<button class="primary" onclick="finishTake()">${t('finish')}</button>`):''}</div><div class="tiny evidence-line">${statusLabel(e)}${e.hints?` · ${t('hintUsed')}: ${e.hints}`:''}${e.attempts?` · ${t('attempts')}: ${e.attempts}`:''}</div></section></aside></div></main>${teacherDrawer()}</div>`}

function takeDiagnostics(){if(state.screen!=='practice')return '';let rows=state.take.map(id=>{let e=state.evidence[id],q=qById(id);return `<div class="diag-row"><div><strong>${id}</strong><small>${familyName(q.family)}</small></div><span>${statusLabel(e)}</span><span>${e?.attempts||0}</span><span>${e?.hints||0}</span><span>${fmtTime(e?.time||0)}</span></div>`}).join('');return `<section class="teacher-diag"><h3>${t('teacherDiagnostics')}</h3><div class="diag-head"><span>${t('question')}</span><span>${t('status')}</span><span>${t('attempts')}</span><span>${t('hint')}</span><span>${t('time')}</span></div>${rows}</section>`}
function teacherHistorySignals(){let weak=weakFamilies(state.level).slice(0,4);if(!weak.length)return `<p class="tiny">${t('noWeakHistory')}</p>`;return `<section class="teacher-diag"><h3>${t('teacherHistory')}</h3><div class="teacher-focus-list">${weak.map(x=>`<button class="secondary" onclick="teacherFocusFamily('${x.family}')">${familyName(x.family)} · ${t('focusFamily')}</button>`).join('')}</div></section>`}
function teacherFocusFamily(f){state.family=f;state.mode='family';state.teacher=false;startTake()}
function teacherJump(id){let q=qById(id);if(!q)return;if(!state.teacherSession){captureQuestionDraft();recordTime();state.teacherReturn={screen:state.screen,level:state.level,mode:state.mode,family:state.family,take:[...state.take],originalTake:[...state.originalTake],idx:state.idx,history:[...state.history],evidence:JSON.parse(JSON.stringify(state.evidence)),drafts:JSON.parse(JSON.stringify(state.drafts)),started:state.started,qStarted:state.qStarted,message:state.message,stuckOpen:state.stuckOpen,revisit:state.revisit,historySaved:state.historySaved,rescueQuestion:state.rescueQuestion,teacher:state.teacher,teacherReveal:state.teacherReveal,teacherRevealSource:state.teacherRevealSource};}state.teacherSession=true;state.level=q.level;state.take=[id];state.originalTake=[id];state.idx=0;state.history=[];state.evidence={};state.drafts={};state.started=Date.now();state.qStarted=Date.now();state.screen='practice';state.teacher=false;state.teacherReveal=false;state.teacherRevealSource=null;state.message=null;state.stuckOpen=false;state.revisit=false;state.historySaved=false;state.rescueQuestion=null;state.renderedQuestionId=null;render();window.scrollTo(0,0)}
function teacherSetLevel(l){if(!['all','core','challenge','advanced'].includes(l))return;state.teacherLevelFilter=l;render()}
function teacherDrawer(){if(!state.teacher)return '';let filtered=BANK.filter(q=>state.teacherLevelFilter==='all'||q.level===state.teacherLevelFilter);return `<div class="overlay" onclick="toggleTeacher()"></div><aside class="teacher-drawer"><div class="teacher-top"><div><div class="eyebrow">${t('teacherView')}</div><h2>${t('selectQuestion')}</h2></div><button class="ghost" onclick="toggleTeacher()">${t('close')}</button></div><p class="tiny">${state.lang==='en'?'Teacher Pass can inspect evidence and jump directly to any validated Practice Bank question without changing student evidence.':'Teacher Pass dapat melihat bukti dan membuka soal tervalidasi mana pun tanpa mengubah bukti siswa.'}</p><div class="teacher-levels">${[['all',state.lang==='en'?'All':'Semua'],['core',t('core')],['challenge',t('challenge')],['advanced',t('advanced')]].map(([l,label])=>`<button class="secondary ${state.teacherLevelFilter===l?'selected':''}" onclick="teacherSetLevel('${l}')">${label}</button>`).join('')}</div>${state.screen==='practice'?`<div class="teacher-actions"><button class="secondary" onclick="teacherRevealSolution()">${state.teacherReveal&&state.teacherRevealSource==='teacher'?t('hide'):t('reveal')}</button>${state.teacherSession?`<button class="primary" onclick="returnTeacherJump()">${state.lang==='en'?'Return to student practice':'Kembali ke latihan siswa'}</button>`:''}</div>${!state.teacherSession?takeDiagnostics():''}`:''}${teacherHistorySignals()}<div class="teacher-list">${filtered.map(q=>`<div class="teacher-item"><div><strong>${q.id} · ${q.title[state.lang]}</strong><br><small>${levelName(q.level)} · ${familyName(q.family)}</small></div><button class="secondary" onclick="teacherJump('${q.id}')">${t('jump')}</button></div>`).join('')}</div></aside>`}



function teacherRevealSolution(){if(!cur())return;let hide=state.teacherReveal&&state.teacherRevealSource==='teacher';state.teacherReveal=!hide;state.teacherRevealSource=hide?null:'teacher';state.teacher=false;render()}
function returnTeacherJump(){if(!state.teacherSession||!state.teacherReturn)return;let r=state.teacherReturn,lang=state.lang;state.screen=r.screen;state.level=r.level;state.mode=r.mode;state.family=r.family;state.take=r.take;state.originalTake=r.originalTake;state.idx=r.idx;state.history=r.history;state.evidence=r.evidence;state.drafts=r.drafts;state.started=r.started;state.qStarted=Date.now();state.message=r.message;state.stuckOpen=r.stuckOpen;state.revisit=r.revisit;state.historySaved=r.historySaved;state.rescueQuestion=r.rescueQuestion;state.teacherReveal=r.teacherReveal;state.teacherRevealSource=r.teacherRevealSource;state.teacher=!!r.teacher;state.lang=lang;state.teacherSession=false;state.teacherReturn=null;state.renderedQuestionId=null;render();window.scrollTo(0,0)}

function renderReport(){let ev=Object.entries(state.evidence).filter(([_,e])=>engagedEvidence(e));let completed=ev.filter(([_,e])=>['independent','supported','recovered','rescued'].includes(e.status)).length,independent=ev.filter(([_,e])=>e.status==='independent').length,supported=ev.filter(([_,e])=>e.status==='supported').length,recovered=ev.filter(([_,e])=>e.status==='recovered').length,rescued=ev.filter(([_,e])=>e.status==='rescued').length,skipped=ev.filter(([_,e])=>e.skipped||!e.status||e.status==='needs-review').length,totalTime=ev.reduce((a,[_,e])=>a+e.time,0);let byFam={};ev.forEach(([id,e])=>{let q=qById(id);if(!q)return;(byFam[q.family]??=[]).push(e)});let strong=Object.entries(byFam).filter(([_,arr])=>arr.some(e=>e.status==='independent'||e.status==='recovered')).map(([f])=>familyName(f));let weakRaw=Object.entries(byFam).filter(([_,arr])=>arr.some(e=>e.status==='rescued'||e.status==='needs-review'||e.skipped||!e.status||e.attempts>1)),weak=weakRaw.map(([f])=>familyName(f)),weakFamily=weakRaw[0]?.[0]||recommendedHistoryFocus();let nextText=weakFamily?(state.lang==='en'?`Revisit ${familyName(weakFamily)} through another structural variation before your next mixed take.`:`Ulangi ${familyName(weakFamily)} melalui variasi struktur lain sebelum mencoba paket campuran berikutnya.`):(state.lang==='en'?'No clear weak family appeared in this take. A new mixed take or a deeper level would provide more evidence.':'Belum terlihat keluarga soal yang jelas perlu diulang. Paket campuran baru atau tingkat yang lebih dalam dapat memberi bukti tambahan.');return `<div class="shell">${topbar()}<main class="report"><div class="eyebrow">${t('report')}</div><h1 style="font-size:48px">${t('summary')}</h1><div class="report-grid phase3-report"><div class="panel metric"><strong>${completed}</strong><span>${t('completed')}</span></div><div class="panel metric"><strong>${independent}</strong><span>${t('independent')}</span></div><div class="panel metric"><strong>${supported}</strong><span>${t('supported')}</span></div><div class="panel metric"><strong>${recovered}</strong><span>${t('recovered')}</span></div><div class="panel metric"><strong>${rescued}</strong><span>${t('rescued')}</span></div><div class="panel metric"><strong>${skipped}</strong><span>${t('skipped')}</span></div></div><section class="panel report-section"><h3>${t('wentWell')}</h3><p>${strong.length?strong.join(' · '):t('noData')}</p></section><section class="panel report-section"><h3>${t('needsLook')}</h3><p>${weak.length?weak.join(' · '):(state.lang==='en'?'No specific difficulty pattern appeared in this take.':'Belum terlihat pola kesulitan tertentu pada paket ini.')}</p></section><section class="panel report-section"><h3>${t('howWorked')}</h3><ul><li>${ev.reduce((a,[_,e])=>a+e.hints,0)} ${state.lang==='en'?'hint steps used':'tahap petunjuk digunakan'}</li><li>${ev.reduce((a,[_,e])=>a+e.stuck,0)} ${state.lang==='en'?"'I'm Stuck' support requests":'permintaan bantuan Aku Buntu'}</li><li>${ev.reduce((a,[_,e])=>a+e.attempts,0)} ${state.lang==='en'?'answer checks / reasoning comparisons':'pengecekan jawaban / perbandingan penalaran'}</li><li>${rescued} ${state.lang==='en'?'worked rescues used':'panduan penyelamatan digunakan'}</li></ul></section><section class="panel report-section"><h3>${t('pacing')}</h3><p>${state.lang==='en'?`Recorded active question time: ${fmtTime(totalTime)}. Timing is descriptive only; slower work is not treated as weaker understanding.`:`Waktu aktif pada soal yang tercatat: ${fmtTime(totalTime)}. Waktu hanya bersifat deskriptif; pengerjaan lebih lambat tidak dianggap sebagai pemahaman yang lebih lemah.`}</p></section><section class="panel report-section"><h3>${t('nextStep')}</h3><p>${nextText}</p><div class="action-row"><button class="primary" onclick="state.mode='standard';startTake()">${t('newMix')}</button><button class="secondary" onclick="startTake('weak')">${t('reviewWeak')}</button><button class="secondary" onclick="startTake('retry')">${t('retryMistakes')}</button>${weakFamily?`<button class="secondary" onclick="state.family='${weakFamily}';state.mode='family';startTake()">${t('focusFamily')}: ${familyName(weakFamily)}</button>`:''}<button class="ghost" onclick="goHome()">${t('backHome')}</button></div></section><div class="mascot-wrap" style="min-height:180px"><img src="${mascot('celebrate')}" style="max-height:170px" alt=""/></div></main>${teacherDrawer()}</div>`}

function isResolvedEvidence(e){return !!(e&&e.status&&e.status!=='needs-review')}
function refreshVisualHint(){let q=cur();if(!q)return;let e=ensureEvidence(q.id),box=document.getElementById('question-visual');if(box)box.innerHTML=renderVisual(q.visual,Math.min(e.hints,3),q);let hc=document.getElementById('hint-copy');if(hc)hc.innerHTML=e.hints?`<div class="hint-box"><strong>${t('hint')} ${e.hints}</strong><div>${q.hints[state.lang][Math.min(e.hints-1,q.hints[state.lang].length-1)]}</div></div>`:'';let mc=document.getElementById('message-copy');if(mc)mc.innerHTML='';let ev=document.querySelector('.evidence-line');if(ev)ev.innerHTML=`${statusLabel(e)}${e.hints?` · ${t('hintUsed')}: ${e.hints}`:''}${e.attempts?` · ${t('attempts')}: ${e.attempts}`:''}`}
function showHint(){let q=cur(),e=q?ensureEvidence(q.id):null;if(!q||isResolvedEvidence(e))return;captureQuestionDraft();e.hints=Math.min(e.hints+1,q.hints[state.lang].length);state.message=null;refreshVisualHint();persistActiveTake()}
function recommendedHistoryFocus(level=state.level){let valid=new Set(BANK.filter(q=>q.level===level).map(q=>q.family));let all=[...valid].map(f=>({family:f,value:familyNeedValue(f)})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);return all[0]?.family||null}
function changeProblem(){let q=cur(),e=q?ensureEvidence(q.id):null;if(!q||isResolvedEvidence(e))return;captureQuestionDraft();recordTime();let used=new Set([...state.take,...state.history]),same=BANK.filter(x=>x.level===state.level&&x.family===q.family&&!used.has(x.id)),different=BANK.filter(x=>x.level===state.level&&x.family!==q.family&&!used.has(x.id)),pool=['family','weak','retry'].includes(state.mode)?[...same,...different]:[...different,...same];if(!pool.length)pool=BANK.filter(x=>x.level===state.level&&x.id!==q.id);if(!pool.length)return;state.take[state.idx]=orderAdaptive(pool,state.mode)[0].id;state.qStarted=Date.now();state.message={type:'warn',text:t('changedMsg')};state.stuckOpen=false;state.teacherReveal=false;state.teacherRevealSource=null;state.rescueQuestion=null;render()}




